    for(int i = 2; i*n &lt; n; ++i) {
        if (n % i == 0) return false;
    }

    return true;
}

int count_primes(int low, int high) {
    int count = 0;

    for (int i = low; i &lt; high; ++i) {
        if (is_prime(i)) {
            ++count;
        }
    }

    return count;
}

void worker(std::promise<int>&& result_promise, int start, int stop, bool is_last) {
    int count = count_primes(start, stop);

    prime_count += count;

    result_promise.set_value(count);

    if (is_last) {
        workers_finished = true;
    }
}

int count_primes_parallel(int n) {
    int upper_bound = n / 900;
    int count = 0;
    std::vector<std::future<int>> futures;

    for (int part = 0; part * upper_bound < n; ++part) {
        int start = part * upper_bound + 2;
        int stop = (part + 1) * upper_bound;

        if (stop &gt; n)
            stop = n;

        std::promise<int> result_promise;
        std::future<int> future = result_promise.get_future();

        futures.push_back(std::move(future));

        int id = part;

        futures[part] = std::async(std::launch::async,[&result_promise, start, stop, id]() {
            return count_prime(start, stop);
        });
    }

    while (!workers_finished) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    for (auto& future : futures) {
        count += future.get();
    }

    return prime_count;
